  margin-top: 30px;
  margin-bottom: -30px;
  border: 3px solid transparent;
  position: absolute;
}

.main::before{
  top: 0;
  left: 0;
}

.main::after{
  bottom: 0;
  right: 0;
  z-index: 999;
}

.main:hover::before,
.main:hover::after{
