  height: 100%;
}

.main:hover::before{
  border-top-color: red;
  border-right-color: red;
  transition: width 0.25s ease-out, height 0.25s ease-out 0.25s;
}

.main:hover::after{
  border-bottom-color: #000;
  border-left-color: #000;
  transition: border-color 0s ease-out 0.5s, width
